(function(g){'use strict';function dec(n){if(typeof n!=='number'||!isFinite(n))return 0;const s=n.toString();if(s.includes('.')){const d=s.split('.')[1];if(parseInt(d,10)!==0)return d.length;}return 0;}function fmt(v,d,s,p,x){p=p||'';x=x||'';const o={useGrouping:!!s,minimumFractionDigits:d>0?d:0,maximumFractionDigits:d>0?d:0};let f=Intl.NumberFormat('en-US',o).format(v);if(s)f=f.replace(/,/g,s);return p+f+x;}function init(el,opts){if(!el)return null;opts=opts||{};const to=opts.to!==undefined?opts.to:(el.dataset.to!==undefined?parseFloat(el.dataset.to):parseFloat(el.dataset.count||el.textContent.replace(/[^\d.-]/g,'')||0));const from=opts.from!==undefined?opts.from:(el.dataset.from!==undefined?parseFloat(el.dataset.from):0);const dir=opts.direction||el.dataset.direction||'up';const delay=opts.delay!==undefined?+opts.delay:(el.dataset.delay?+el.dataset.delay:0);const dur=opts.duration!==undefined?+opts.duration:(el.dataset.duration?+el.dataset.duration:2);const sep=opts.separator!==undefined?opts.separator:(el.dataset.separator!==undefined?el.dataset.separator:'');const pfx=opts.prefix!==undefined?opts.prefix:(el.dataset.prefix||'');const sfx=opts.suffix!==undefined?opts.suffix:(el.dataset.suffix||'');const startWhen=opts.startWhen!==undefined?opts.startWhen:true;const once=opts.once!==undefined?opts.once:true;const onStart=opts.onStart||null;const onEnd=opts.onEnd||null;const targetVal=dir==='down'?from:to;const initVal=dir==='down'?to:from;const maxD=Math.max(dec(from),dec(to));const sDur=Math.max(dur,0.05);const damp=20+40*(1/sDur);const stiff=100*(1/sDur);let cur=initVal,vel=0,raf=null,tDel=null,tEnd=null,running=false,triggered=false,startTime=0;el.textContent=fmt(initVal,maxD,sep,pfx,sfx);function step(dt,elap){const subs=4,sdt=Math.min(dt,0.064)/subs;for(let i=0;i<subs;i++){const disp=cur-targetVal;const f=-stiff*disp-damp*vel;vel+=f*sdt;cur+=vel*sdt;}const diff=Math.abs(cur-targetVal);const th=maxD>0?0.002:0.25;const settled=(diff<th&&Math.abs(vel)<0.6)||(elap>=sDur&&diff<0.5);if(settled){cur=targetVal;vel=0;el.textContent=fmt(cur,maxD,sep,pfx,sfx);running=false;if(typeof onEnd==='function')onEnd();return false;}el.textContent=fmt(cur,maxD,sep,pfx,sfx);return true;}let last=0;function loop(t){if(!last){last=t;startTime=t;}const dt=(t-last)/1000;const elap=(t-startTime)/1000;last=t;if(step(dt,elap))raf=requestAnimationFrame(loop);}function start(){if(running)return;triggered=true;running=true;if(typeof onStart==='function')onStart();tDel=setTimeout(()=>{last=0;startTime=0;raf=requestAnimationFrame(loop);},delay*1000);tEnd=setTimeout(()=>{if(running){if(raf)cancelAnimationFrame(raf);cur=targetVal;el.textContent=fmt(cur,maxD,sep,pfx,sfx);running=false;if(typeof onEnd==='function')onEnd();}},(delay+sDur*1.25)*1000);}function rst(){if(raf)cancelAnimationFrame(raf);clearTimeout(tDel);clearTimeout(tEnd);running=false;triggered=false;cur=initVal;vel=0;el.textContent=fmt(initVal,maxD,sep,pfx,sfx);}let obs=null;if(typeof IntersectionObserver!=='undefined'&&startWhen){obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){if(!triggered){start();if(once&&obs)obs.unobserve(el);}}else if(!once&&triggered){rst();}});},{threshold:0.15});obs.observe(el);}else if(startWhen){start();}return{start,reset:rst,restart:()=>{rst();start();},destroy:()=>{if(raf)cancelAnimationFrame(raf);clearTimeout(tDel);clearTimeout(tEnd);if(obs){obs.disconnect();obs=null;}}};}function initAll(sel){const list=document.querySelectorAll(sel||'.count-up, [data-count], .stat-number');const res=[];list.forEach(el=>{if(!el._countUpInstance){el._countUpInstance=init(el);res.push(el._countUpInstance);}});return res;}g.initCountUp=init;g.initAllCountUps=initAll;if(typeof document!=='undefined'){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>initAll());}else{initAll();}}})(typeof window!=='undefined'?window:this);
